import math

def grad(x, y):
    return [2 * x, 6 * y]

def steepest(x, y):
    g = grad(x, y)
    length = math.hypot(g[0], g[1])
    if length == 0:
        raise ValueError("flat: no uphill direction")
    return [g[0] / length, g[1] / length]

