problems.solution:
import numpy as np

def fit(x, y, lr=0.05, steps=2000):
    w, b = 0.0, 0.0
    for _ in range(steps):
        err = w * x + b - y
        dw = np.mean(2 * err * x)
        db = np.mean(2 * err)
        w, b = w - lr * dw, b - lr * db
    return float(w), float(b)
